beforeExample:
import org.eclipse.swt.widgets.Display;

public class Test {
    Display display;

    void foo() {
        display.asyncExec(new java.lang.Runnable() {
            @java.lang.Override
            public void run() {
                System.out.println("Hello from Runnable");
            }
        });
    }
}

afterExample:
import org.eclipse.swt.widgets.Display;

public class Test {
    Display display;

    void foo() {
        display.asyncExec(() -> {
            System.out.println("Hello from Runnable");
        });
    }
}

negativeExample:
import java.util.concurrent.Callable;
import org.eclipse.swt.widgets.Display;

public class Test {
    Display display;

    void bar() {
        // This Callable should not match the Runnable rule
        Callable<String> c = new Callable<String>() {
            @java.lang.Override
            public String call() throws Exception {
                return "Hello from Callable";
            }
        };
        System.out.println(c.toString());

        // Another anonymous class not implementing Runnable
        Object o = new Object() {
            public void doWork() {
                System.out.println("Doing work");
            }
        };
    }
}
